/* eslint-disable no-new */

'use strict';

// MODULES //

var tape = require( 'tape' );
var isNumberOrComplexLike = require( '@stdlib/assert/is-number-or-complex-like' ).isPrimitive;
var isndarrayLikeWithDataType = require( '@stdlib/assert/is-ndarray-like-with-data-type' );
var isSameComplex128Array = require( '@stdlib/assert/is-same-complex128array' );
var isReadOnly = require( '@stdlib/ndarray/base/assert/is-read-only' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var Complex128Array = require( '@stdlib/array/complex128' );
var getData = require( '@stdlib/ndarray/data-buffer' );
var numel = require( '@stdlib/ndarray/numel' );
var getOrder = require( '@stdlib/ndarray/order' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var ZERO = require( '@stdlib/constants/complex128/zero' );
var factory = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid data type', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			factory( value, 1.0, isNumberOrComplexLike );
		};
	}
});

