tape( 'the function returns a function', function test( t ) {
	var ctor;

	ctor = factory( 'complex128', 0.0, isNumberOrComplexLike );
	t.strictEqual( typeof ctor, 'function', 'returns expected value' );

	ctor = factory( 'complex128', ZERO, isNumberOrComplexLike );
	t.strictEqual( typeof ctor, 'function', 'returns expected value' );

	t.end();
});

