tape( 'the function returns a function which supports specifying the memory layout', function test( t ) {
	var ctor;
	var arr;

	ctor = factory( 'complex128', ZERO, isNumberOrComplexLike );

	arr = new ctor({
		'order': 'row-major'
	});
	t.strictEqual( isndarrayLikeWithDataType( arr, 'complex128' ), true, 'returns expected value' );
	t.strictEqual( numel( arr ), 1, 'returns expected value' );
	t.strictEqual( getOrder( arr ), 'row-major', 'returns expected value' );

	arr = new ctor({
		'order': 'column-major'
	});
	t.strictEqual( isndarrayLikeWithDataType( arr, 'complex128' ), true, 'returns expected value' );
	t.strictEqual( numel( arr ), 1, 'returns expected value' );
	t.strictEqual( getOrder( arr ), 'column-major', 'returns expected value' );

	t.end();
});

